import sys

def count_inversions(arr):
    n = len(arr)
    inv = 0
    for i in range(n):
        for j in range(i+1, n):
            if arr[i] > arr[j]:
                inv += 1
    return inv

def solve():
    input = sys.stdin.read().split()
    ptr = 0
    T = int(input[ptr])
    ptr += 1
    for _ in range(T):
        N = int(input[ptr])
        ptr += 1
        arr = list(map(int, input[ptr:ptr+N]))
        ptr += N

        max_inv = -1
        best_k = 0
        for k in range(N):
            rotated = arr[k:] + arr[:k]
            inv = count_inversions(rotated)
            if inv > max_inv or (inv == max_inv and k < best_k):
                max_inv = inv
                best_k = k
            elif inv == max_inv:
                if k < best_k:
                    best_k = k
        print(best_k, max_inv)

solve()
